// GENERATOR — callable by name from any request body or metadata script in this
// collection. The default export is the function; the script's name is the
// global it is bound to, so a body just writes:
//
//   { id: requestId(), scoped: requestId("order") }
//
// Every sandbox instance starts from the same seed, so Math.random() here is
// reproducible across runs rather than unique — fine for a demo id, not a
// substitute for a real uuid.

const hex = (n: number): string =>
  Array.from({ length: n }, () => Math.floor(Math.random() * 16).toString(16)).join("");

export default (prefix = "req"): string => `${prefix}_${hex(8)}${hex(4)}`;
